/**
 * Custom flight paths: routes imported from files, pasted flight plans or agent documents, kept exactly as
 * given (point order, positions, altitudes, times and provenance) rather than generated by GlobeHops.
 *
 * A flight's drawn path has one of three origins (`PathKind`):
 * - `generated`: GlobeHops' own great circle, or its airspace/diversion-aware route (no track);
 * - `planned`: a path someone intends to fly (a flight plan, a GPX route, a GeoJSON line), without
 *   recorded times; altitudes, when given, are planned levels;
 * - `recorded`: a path that was flown (an ADS-B export, a GPS or IGC log), with at least two timestamps;
 *   its times and altitudes take precedence over every estimate.
 *
 * A track belongs to one flight, between two airports. Imports match the path's ends to airports (the
 * stops), but never move the path: its first and last points need not be the airports' positions.
 */
import type { LatLng } from '../types.ts';

export type PathKind = 'generated' | 'planned' | 'recorded';
export type TrackKind = Exclude<PathKind, 'generated'>;

export interface TrackPoint {
  lat: number;
  lng: number;
  /** Altitude above mean sea level in metres; null when unknown. */
  altM: number | null;
  /** UTC instant in epoch milliseconds; null when unknown. */
  time: number | null;
  /** A planned route's waypoint identifier (e.g. `CPT`, `KONAN`, `EGLL`); absent otherwise. */
  name?: string;
}

/** Formats GlobeHops reads. `route` is an aviation route string; `link` a track carried by a share link. */
export type TrackFormat =
  'geojson' | 'gpx' | 'kml' | 'kmz' | 'csv' | 'igc' | 'fpl' | 'pln' | 'route' | 'link' | 'document';

export interface TrackSource {
  format: TrackFormat;
  /** A short name: the file name, a track's own name, or null. Never the file's contents. */
  name: string | null;
}

/** One flight's imported path, exactly as given. */
export interface CustomTrack {
  kind: TrackKind;
  /** At least two points, in flight order. */
  points: TrackPoint[];
  source: TrackSource;
  /**
   * The number of points before the track was simplified to fit a share link; absent when exact. Paths
   * are only ever simplified for links, never in the session that imported them.
   */
  reducedFrom?: number;
}

/** A flight's custom path as the schedule, timeline and globe use it (derived from a `CustomTrack`). */
export interface LegTrack {
  kind: TrackKind;
  source: TrackSource;
  /** The track's positions; the same array object for the life of the track (geometry caches key on it). */
  path: LatLng[];
  /** Altitudes in kilometres aligned with `path`, or null when any is unknown. */
  altitudesKm: number[] | null;
  /** Epoch milliseconds aligned with `path` (non-decreasing), or null unless the track is recorded. */
  times: number[] | null;
  /** Length of the path along the sphere (km). */
  distanceKm: number;
  /** Points in the track, and before link simplification (equal when exact). */
  points: number;
  reducedFrom: number | null;
}
